diffs.patch:
Index: project/index.html
===================================================================
--- project/index.html	
+++ project/index.html	
@@ -0,0 +1,646 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
+<title>Orbit Orchard — a tiny astronaut gardening game</title>
+<style>
+  :root{
+    --hud-bg: rgba(10,14,34,.72);
+    --hud-border: rgba(255,255,255,.14);
+    --accent: #7CFFB2;
+    --accent2:#FFD166;
+    --danger:#FF6B6B;
+    --text:#F4F7FF;
+    --muted:#9AA6C7;
+  }
+  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
+  html,body{height:100%}
+  body{
+    margin:0;overflow:hidden;background:#050816;color:var(--text);
+    font-family:"Avenir Next","Segoe UI",system-ui,-apple-system,Roboto,"Helvetica Neue",Arial,sans-serif;
+    user-select:none;-webkit-user-select:none;touch-action:none;
+  }
+  #scene{position:fixed;inset:0;display:block}
+  .vignette{position:fixed;inset:0;pointer-events:none;
+    background:radial-gradient(ellipse at 50% 45%, transparent 55%, rgba(0,0,10,.55) 100%);}
+  /* ---------- HUD ---------- */
+  #hud{
+    position:fixed;top:0;left:0;right:0;z-index:10;
+    display:flex;align-items:stretch;justify-content:center;gap:10px;
+    padding:12px 12px 0 12px;pointer-events:none;
+  }
+  .pill{
+    pointer-events:auto;
+    display:flex;align-items:center;gap:10px;
+    background:var(--hud-bg);border:1px solid var(--hud-border);
+    border-radius:16px;padding:8px 14px;
+    backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);
+    box-shadow:0 8px 24px rgba(0,0,0,.35);
+    min-height:52px;
+  }
+  .pill .label{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:700}
+  #fruitCount{font-size:22px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1}
+  #fruitCount.pop{animation:pop .35s ease}
+  @keyframes pop{40%{transform:scale(1.35) rotate(-4deg)}100%{transform:scale(1)}}
+  .fruit-ico{font-size:22px;filter:drop-shadow(0 0 8px rgba(255,209,102,.9))}
+  #timerWrap{min-width:200px;flex-direction:column;align-items:stretch;gap:6px}
+  #timerRow{display:flex;align-items:center;justify-content:space-between;gap:12px}
+  #timerText{font-size:22px;font-weight:800;font-variant-numeric:tabular-nums}
+  #timerText.warning{color:var(--danger);animation:blink .7s steps(2) infinite}
+  @keyframes blink{50%{opacity:.45}}
+  #timebar{height:8px;border-radius:99px;background:rgba(255,255,255,.12);overflow:hidden}
+  #timefill{height:100%;width:100%;border-radius:99px;
+    background:linear-gradient(90deg,var(--accent),var(--accent2));
+    transition:width .2s linear}
+  #timefill.low{background:linear-gradient(90deg,#ff9a3d,var(--danger))}
+  #restartBtn{
+    cursor:pointer;border:1px solid var(--hud-border);border-radius:16px;
+    background:var(--hud-bg);color:var(--text);
+    font-size:15px;font-weight:700;padding:0 18px;min-height:52px;
+    backdrop-filter:blur(10px);display:flex;align-items:center;gap:8px;
+    transition:transform .08s ease, background .15s ease;
+  }
+  #restartBtn:hover{background:rgba(60,80,160,.7)}
+  #restartBtn:active{transform:scale(.94)}
+  #muteBtn{
+    cursor:pointer;border:1px solid var(--hud-border);border-radius:16px;
+    background:var(--hud-bg);color:var(--text);
+    font-size:18px;padding:0 14px;min-height:52px;
+  }
+  /* ---------- Hint / toast ---------- */
+  #hint{
+    position:fixed;left:50%;bottom:118px;transform:translateX(-50%);z-index:9;
+    background:rgba(10,14,34,.66);border:1px solid var(--hud-border);
+    padding:8px 16px;border-radius:99px;font-size:13px;color:#D6DDF5;
+    backdrop-filter:blur(8px);white-space:nowrap;pointer-events:none;
+    transition:opacity .4s ease;
+  }
+  #hint kbd{
+    background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.2);
+    border-bottom-width:2px;border-radius:6px;padding:1px 6px;font-size:12px;font-family:inherit;
+  }
+  /* ---------- Touch controls ---------- */
+  #touch{
+    position:fixed;left:0;right:0;bottom:0;z-index:10;
+    display:flex;justify-content:space-between;align-items:flex-end;
+    padding:0 18px calc(18px + env(safe-area-inset-bottom));
+    pointer-events:none;
+  }
+  .tbtn{
+    pointer-events:auto;
+    width:84px;height:84px;border-radius:50%;
+    border:2px solid rgba(255,255,255,.22);
+    background:rgba(20,28,64,.55);color:#fff;font-size:34px;
+    backdrop-filter:blur(8px);box-shadow:0 8px 24px rgba(0,0,0,.4);
+    display:flex;align-items:center;justify-content:center;
+    touch-action:none;cursor:pointer;transition:transform .06s ease, background .12s;
+  }
+  .tbtn.active{background:rgba(124,255,178,.35);transform:scale(.92)}
+  #touchMid{
+    pointer-events:none;text-align:center;font-size:12px;color:var(--muted);
+    padding-bottom:10px;text-shadow:0 2px 8px #000;
+  }
+  /* ---------- Overlays ---------- */
+  .overlay{
+    position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;
+    background:rgba(4,6,18,.62);backdrop-filter:blur(6px);padding:20px;
+    opacity:1;transition:opacity .3s ease;
+  }
+  .overlay.hidden{opacity:0;pointer-events:none}
+  .card{
+    max-width:460px;width:100%;text-align:center;
+    background:linear-gradient(180deg,rgba(24,32,72,.96),rgba(12,17,42,.96));
+    border:1px solid rgba(255,255,255,.16);border-radius:24px;
+    padding:34px 30px 28px 30px;box-shadow:0 30px 80px rgba(0,0,0,.6);
+  }
+  .card .eyebrow{font-size:12px;letter-spacing:.22em;color:var(--accent);font-weight:800;text-transform:uppercase}
+  .card h1{margin:8px 0 6px 0;font-size:38px;letter-spacing:.01em}
+  .card h1 .orbit{color:var(--accent2)}
+  .card p{color:#C4CDEA;font-size:15px;line-height:1.55;margin:8px 0}
+  .stat-row{display:flex;gap:10px;justify-content:center;margin:16px 0}
+  .stat{background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);
+    border-radius:14px;padding:10px 18px;min-width:120px}
+  .stat b{display:block;font-size:24px}
+  .stat span{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
+  .bigbtn{
+    cursor:pointer;border:none;border-radius:14px;margin-top:10px;
+    font-size:18px;font-weight:800;color:#06130C;width:100%;padding:15px;
+    background:linear-gradient(180deg,#8FFFC0,#4ADE80);
+    box-shadow:0 10px 30px rgba(74,222,128,.35);
+    transition:transform .08s ease, filter .15s;
+  }
+  .bigbtn:hover{filter:brightness(1.06)}
+  .bigbtn:active{transform:scale(.97)}
+  .keys{margin-top:14px;font-size:13px;color:var(--muted)}
+  .keys kbd{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);
+    border-bottom-width:2px;border-radius:6px;padding:2px 8px;font-family:inherit;color:#fff}
+  #winCard h1{color:var(--accent)}
+  #loseCard h1{color:var(--danger)}
+  .fruit-burst{font-size:30px;animation:floaty 2s ease-in-out infinite;display:inline-block}
+  @keyframes floaty{50%{transform:translateY(-6px) rotate(8deg)}}
+  @media (max-width:640px){
+    #timerWrap{min-width:0;flex:1}
+    .pill{padding:6px 10px;min-height:48px}
+    #fruitCount,#timerText{font-size:18px}
+    #hint{display:none}
+    .card h1{font-size:30px}
+  }
+</style>
+</head>
+<body>
+<canvas id="scene"></canvas>
+<div class="vignette"></div>
+
+<div id="hud">
+  <div class="pill" id="fruitPill" aria-live="polite">
+    <span class="fruit-ico">🍎</span>
+    <div>
+      <div class="label">Fruit</div>
+      <div id="fruitCount">0 / 8</div>
+    </div>
+  </div>
+  <div class="pill" id="timerWrap">
+    <div id="timerRow">
+      <span class="label">⏱ Time</span>
+      <span id="timerText">60.0</span>
+    </div>
+    <div id="timebar"><div id="timefill"></div></div>
+  </div>
+  <button id="restartBtn" title="Restart (R)">↻ Restart</button>
+  <button id="muteBtn" title="Mute sound">🔊</button>
+</div>
+
+<div id="hint"><kbd>◀</kbd> <kbd>▶</kbd> or <kbd>A</kbd> <kbd>D</kbd> to run around &nbsp;•&nbsp; grab all 8 fruit!</div>
+
+<div id="touch">
+  <div class="tbtn" id="btnLeft" aria-label="Move left">◀</div>
+  <div id="touchMid">hold buttons or drag<br>to orbit</div>
+  <div class="tbtn" id="btnRight" aria-label="Move right">▶</div>
+</div>
+
+<div class="overlay" id="startOverlay">
+  <div class="card">
+    <div class="eyebrow">🪐 A tiny gardening mission</div>
+    <h1>Orbit <span class="orbit">Orchard</span></h1>
+    <p>You are a <b>gardener astronaut</b> on a pocket-sized planet.<br>
+    Run around its orbit and collect <b>8 glowing fruit</b> before the
+    <b>60-second</b> timer runs out!</p>
+    <div class="stat-row">
+      <div class="stat"><b>🍎 8</b><span>fruit to pick</span></div>
+      <div class="stat"><b>⏱ 60s</b><span>on the clock</span></div>
+    </div>
+    <button class="bigbtn" id="startBtn">▶ Start gardening</button>
+    <div class="keys"><kbd>◀</kbd> <kbd>▶</kbd> / <kbd>A</kbd> <kbd>D</kbd> &nbsp;•&nbsp; touch buttons or drag on mobile &nbsp;•&nbsp; <kbd>R</kbd> restarts</div>
+  </div>
+</div>
+
+<div class="overlay hidden" id="winCard">
+  <div class="card">
+    <div class="fruit-burst">🍎✨🍐✨🍊</div>
+    <div class="eyebrow">Harvest complete</div>
+    <h1>You did it! 🎉</h1>
+    <p id="winText">All 8 fruit collected!</p>
+    <div class="stat-row">
+      <div class="stat"><b id="winTime">—</b><span id="winTimeLabel">harvest time</span></div>
+      <div class="stat"><b>🍎 8/8</b><span>fruit picked</span></div>
+    </div>
+    <button class="bigbtn" id="winRestart">↻ Play again</button>
+  </div>
+</div>
+
+<div class="overlay hidden" id="loseCard">
+  <div class="card">
+    <div class="fruit-burst">🥀💨</div>
+    <div class="eyebrow" style="color:#FF9AA2">Time's up</div>
+    <h1>Out of time…</h1>
+    <p id="loseText">You collected 0 of 8 fruit.</p>
+    <div class="stat-row">
+      <div class="stat"><b id="loseFruit">0/8</b><span>fruit picked</span></div>
+      <div class="stat"><b>⏱ 0s</b><span>remaining</span></div>
+    </div>
+    <button class="bigbtn" id="loseRestart">↻ Try again</button>
+  </div>
+</div>
+
+<script>
+"use strict";
+/* ================= Orbit Orchard ================= */
+const canvas = document.getElementById('scene');
+const ctx = canvas.getContext('2d');
+const FRUIT_GOAL = 8, TIME_LIMIT = 60;
+
+const el = id => document.getElementById(id);
+const fruitCountEl = el('fruitCount'), timerText = el('timerText'), timefill = el('timefill');
+const startOverlay = el('startOverlay'), winCard = el('winCard'), loseCard = el('loseCard');
+const hint = el('hint');
+
+let W = 0, H = 0, DPR = 1, CX = 0, CY = 0, PLANET_R = 100, ORBIT_R = 100;
+function resize(){
+  DPR = Math.min(window.devicePixelRatio || 1, 2);
+  W = window.innerWidth; H = window.innerHeight;
+  canvas.width = Math.round(W * DPR); canvas.height = Math.round(H * DPR);
+  canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
+  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
+  CX = W / 2; CY = H * 0.52;
+  PLANET_R = Math.max(90, Math.min(W, H) * 0.27);
+  ORBIT_R = PLANET_R + 26;
+}
+window.addEventListener('resize', resize); resize();
+
+/* ---------- audio (tiny synth, no assets) ---------- */
+let audioCtx = null, muted = false;
+function audio(){ if(!audioCtx){ audioCtx = new (window.AudioContext||window.webkitAudioContext)(); } return audioCtx; }
+function beep(freq, dur, type, vol, when){
+  if(muted) return;
+  try{
+    const a = audio(), t = a.currentTime + (when||0);
+    const o = a.createOscillator(), g = a.createGain();
+    o.type = type || 'sine'; o.frequency.setValueAtTime(freq, t);
+    g.gain.setValueAtTime(0.0001, t);
+    g.gain.exponentialRampToValueAtTime(vol||0.18, t+0.015);
+    g.gain.exponentialRampToValueAtTime(0.0001, t+dur);
+    o.connect(g).connect(a.destination); o.start(t); o.stop(t+dur+0.05);
+  }catch(e){}
+}
+const sfx = {
+  pickup(n){ const base = 520 + n*70; beep(base, .18, 'sine', .22); beep(base*1.5, .22, 'triangle', .14, .05); },
+  win(){ [523,659,784,1046,1318].forEach((f,i)=>beep(f,.35,'triangle',.2,i*.11)); },
+  lose(){ [400,340,280,200].forEach((f,i)=>beep(f,.3,'sawtooth',.08,i*.13)); },
+  step(){ beep(180+Math.random()*60,.06,'square',.03); },
+  click(){ beep(700,.07,'sine',.12); }
+};
+el('muteBtn').addEventListener('click', ()=>{
+  muted = !muted; el('muteBtn').textContent = muted ? '🔇' : '🔊';
+});
+
+/* ---------- game state ---------- */
+const FRUIT_EMOJI = ['🍎','🍐','🍊','🍋','🍇','🍒','🥭','🍑'];
+let state = 'menu';           // menu | play | win | lose
+let playerAngle = -Math.PI/2; // start at top
+let playerDir = 1, moving = false, moveAmt = 0;
+let collected = 0, timeLeft = TIME_LIMIT, elapsed = 0;
+let fruits = [], particles = [], floaters = [], confetti = [], ripples = [];
+let stars = [], shake = 0, lastStep = 0, runPhase = 0;
+
+function makeStars(){
+  stars = [];
+  for(let i=0;i<160;i++) stars.push({x:Math.random(),y:Math.random(),r:Math.random()*1.6+.3,tw:Math.random()*6.28,sp:.2+Math.random()*.8});
+}
+makeStars();
+
+function resetGame(){
+  collected = 0; timeLeft = TIME_LIMIT; elapsed = 0;
+  playerAngle = -Math.PI/2; playerDir = 1;
+  particles = []; floaters = []; confetti = []; ripples = []; shake = 0;
+  fruits = [];
+  // spread 8 fruit around the circle with jitter, keeping a gap at the spawn point (top)
+  for(let i=0;i<FRUIT_GOAL;i++){
+    const a = -Math.PI/2 + ((i+0.5)/FRUIT_GOAL)*Math.PI*2 + (Math.random()-.5)*0.3;
+    fruits.push({angle:a, emoji:FRUIT_EMOJI[i%FRUIT_EMOJI.length], taken:false, bob:Math.random()*6.28, scale:0});
+  }
+  updateHUD(true);
+}
+function updateHUD(snap){
+  fruitCountEl.textContent = collected + ' / ' + FRUIT_GOAL;
+  timerText.textContent = Math.max(0,timeLeft).toFixed(1);
+  timerText.classList.toggle('warning', timeLeft <= 10 && state==='play');
+  timefill.style.width = (100*Math.max(0,timeLeft)/TIME_LIMIT) + '%';
+  timefill.classList.toggle('low', timeLeft <= 10);
+  if(!snap){
+    fruitCountEl.classList.remove('pop'); void fruitCountEl.offsetWidth;
+    fruitCountEl.classList.add('pop');
+  }
+}
+function startGame(){
+  audio(); // unlock
+  resetGame();
+  state = 'play';
+  startOverlay.classList.add('hidden');
+  winCard.classList.add('hidden'); loseCard.classList.add('hidden');
+  hint.style.opacity = '1';
+  setTimeout(()=>{ hint.style.opacity = '0'; }, 6000);
+}
+function endGame(win){
+  state = win ? 'win' : 'lose';
+  if(win){
+    sfx.win();
+    el('winTime').textContent = elapsed.toFixed(1) + 's';
+    el('winTimeLabel').textContent = 'harvest time';
+    winCard.classList.remove('hidden');
+    for(let i=0;i<140;i++) confetti.push({
+      x:CX+(Math.random()-.5)*200, y:CY-80+(Math.random()-.5)*80,
+      vx:(Math.random()-.5)*320, vy:-Math.random()*320-60,
+      c:['#FFD166','#7CFFB2','#FF6B6B','#8ECAE6','#C8B6FF'][i%5],
+      r:3+Math.random()*4, rot:Math.random()*6.28, vr:(Math.random()-.5)*10, life:2.2+Math.random()
+    });
+  } else {
+    sfx.lose();
+    el('loseText').textContent = 'You collected ' + collected + ' of ' + FRUIT_GOAL + ' fruit. The orchard fades… try again!';
+    el('loseFruit').textContent = collected + '/' + FRUIT_GOAL;
+    loseCard.classList.remove('hidden');
+  }
+}
+
+/* ---------- input: keyboard ---------- */
+const keys = {};
+window.addEventListener('keydown', e=>{
+  if(['ArrowLeft','ArrowRight',' '].includes(e.key)) e.preventDefault();
+  keys[e.key.toLowerCase()] = true;
+  if(e.key==='r'||e.key==='R'){ sfx.click(); startGame(); }
+  if((e.key===' '||e.key==='Enter') && state!=='play'){ sfx.click(); startGame(); }
+});
+window.addEventListener('keyup', e=>{ keys[e.key.toLowerCase()] = false; });
+
+/* ---------- input: touch buttons + drag ---------- */
+let touchLeft = false, touchRight = false;
+function bindHold(elm, set){
+  const on = e=>{ e.preventDefault(); set(true); elm.classList.add('active'); };
+  const off = e=>{ e.preventDefault(); set(false); elm.classList.remove('active'); };
+  elm.addEventListener('pointerdown', on);
+  elm.addEventListener('pointerup', off);
+  elm.addEventListener('pointercancel', off);
+  elm.addEventListener('pointerleave', off);
+  elm.addEventListener('contextmenu', e=>e.preventDefault());
+}
+bindHold(el('btnLeft'), v=>touchLeft=v);
+bindHold(el('btnRight'), v=>touchRight=v);
+
+// drag-to-orbit on canvas
+let dragging = false, lastPX = 0;
+canvas.addEventListener('pointerdown', e=>{ dragging = true; lastPX = e.clientX; });
+window.addEventListener('pointermove', e=>{
+  if(!dragging || state!=='play') return;
+  const dx = e.clientX - lastPX; lastPX = e.clientX;
+  playerAngle += dx * 0.004;
+  moving = true; moveAmt = Math.sign(dx); playerDir = dx >= 0 ? 1 : -1;
+});
+window.addEventListener('pointerup', ()=>dragging=false);
+window.addEventListener('pointercancel', ()=>dragging=false);
+
+el('startBtn').addEventListener('click', ()=>{ sfx.click(); startGame(); });
+el('winRestart').addEventListener('click', ()=>{ sfx.click(); startGame(); });
+el('loseRestart').addEventListener('click', ()=>{ sfx.click(); startGame(); });
+el('restartBtn').addEventListener('click', ()=>{ sfx.click(); startGame(); });
+
+/* ---------- helpers ---------- */
+function angDiff(a,b){ let d=(a-b)%(Math.PI*2); if(d>Math.PI)d-=Math.PI*2; if(d<-Math.PI)d+=Math.PI*2; return d; }
+function pol(angle, radius){ return {x:CX+Math.cos(angle)*radius, y:CY+Math.sin(angle)*radius}; }
+function burst(x,y,color,n,power){
+  for(let i=0;i<(n||18);i++){
+    const a=Math.random()*Math.PI*2, s=(0.4+Math.random()*0.6)*(power||160);
+    particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-60,life:.6+Math.random()*.5,t:0,c:color,r:2+Math.random()*3});
+  }
+}
+
+/* ---------- update ---------- */
+let lastT = performance.now();
+function update(dt){
+  // ambient always
+  for(const s of stars){ s.tw += dt*2; }
+  for(const f of fruits){ f.bob += dt*2.2; if(f.scale<1) f.scale=Math.min(1,f.scale+dt*3); }
+  for(let i=particles.length-1;i>=0;i--){ const p=particles[i]; p.t+=dt;
+    if(p.t>=p.life){particles.splice(i,1);continue;} p.x+=p.vx*dt; p.y+=p.vy*dt; p.vy+=300*dt; }
+  for(let i=floaters.length-1;i>=0;i--){ const f=floaters[i]; f.t+=dt; f.y-=46*dt;
+    if(f.t>=f.life) floaters.splice(i,1); }
+  for(let i=ripples.length-1;i>=0;i--){ const r=ripples[i]; r.t+=dt; if(r.t>=r.life) ripples.splice(i,1); }
+  for(let i=confetti.length-1;i>=0;i--){ const c=confetti[i]; c.life-=dt;
+    if(c.life<=0){confetti.splice(i,1);continue;}
+    c.x+=c.vx*dt; c.y+=c.vy*dt; c.vy+=500*dt; c.rot+=c.vr*dt; }
+  if(shake>0) shake=Math.max(0,shake-dt*3);
+
+  if(state!=='play') return;
+
+  // movement input
+  let dir = 0;
+  if(keys['arrowleft']||keys['a']) dir -= 1;
+  if(keys['arrowright']||keys['d']) dir += 1;
+  if(touchLeft) dir -= 1;
+  if(touchRight) dir += 1;
+  if(dragging && Math.abs(moveAmt)>0){ dir = 0; moveAmt = 0; moving=false; }
+  else { moving = dir!==0; }
+  if(dir!==0){
+    playerDir = dir;
+    const speed = 2.1; // rad/s
+    playerAngle += dir*speed*dt;
+    runPhase += dt*11;
+    if(performance.now()-lastStep>190){ lastStep=performance.now(); sfx.step(); }
+    // jet sparkle
+    const pp = pol(playerAngle, ORBIT_R);
+    if(Math.random()<.35) particles.push({x:pp.x+(Math.random()-.5)*8,y:pp.y+(Math.random()-.5)*8,
+      vx:-dir*60+(Math.random()-.5)*40,vy:-40-Math.random()*40,life:.4,t:0,c:'#7CFFB2',r:1.5+Math.random()*2});
+  }
+
+  // timer
+  elapsed += dt; timeLeft -= dt;
+  if(timeLeft<=0){ timeLeft=0; updateHUD(); endGame(false); return; }
+
+  // collection
+  for(const f of fruits){
+    if(f.taken) continue;
+    if(Math.abs(angDiff(playerAngle,f.angle)) < 0.11){
+      f.taken = true; collected++;
+      const p = pol(f.angle, ORBIT_R);
+      burst(p.x,p.y,'#FFD166',22,200); burst(p.x,p.y,'#7CFFB2',12,120);
+      ripples.push({x:p.x,y:p.y,t:0,life:.5});
+      floaters.push({x:p.x,y:p.y-24,text:'+1 '+f.emoji,t:0,life:.9});
+      shake = 0.6; sfx.pickup(collected);
+      updateHUD();
+      if(collected>=FRUIT_GOAL){ endGame(true); return; }
+    }
+  }
+  // timer HUD every frame
+  timerText.textContent = Math.max(0,timeLeft).toFixed(1);
+  timefill.style.width = (100*Math.max(0,timeLeft)/TIME_LIMIT)+'%';
+  timerText.classList.toggle('warning', timeLeft<=10);
+  timefill.classList.toggle('low', timeLeft<=10);
+}
+
+/* ---------- draw ---------- */
+function draw(t){
+  ctx.clearRect(0,0,W,H);
+  // bg gradient + nebula
+  const g = ctx.createLinearGradient(0,0,0,H);
+  g.addColorStop(0,'#070B26'); g.addColorStop(.55,'#0B1030'); g.addColorStop(1,'#131A3F');
+  ctx.fillStyle = g; ctx.fillRect(0,0,W,H);
+  const neb = ctx.createRadialGradient(W*0.8,H*0.15,10,W*0.8,H*0.15,W*0.5);
+  neb.addColorStop(0,'rgba(120,90,220,.16)'); neb.addColorStop(1,'rgba(120,90,220,0)');
+  ctx.fillStyle=neb; ctx.fillRect(0,0,W,H);
+  const neb2 = ctx.createRadialGradient(W*0.12,H*0.7,10,W*0.12,H*0.7,W*0.45);
+  neb2.addColorStop(0,'rgba(60,200,160,.12)'); neb2.addColorStop(1,'rgba(60,200,160,0)');
+  ctx.fillStyle=neb2; ctx.fillRect(0,0,W,H);
+  // stars
+  for(const s of stars){
+    const a = .35 + .65*Math.abs(Math.sin(s.tw));
+    ctx.globalAlpha = a; ctx.fillStyle = '#DFE8FF';
+    ctx.beginPath(); ctx.arc(s.x*W, s.y*H, s.r, 0, 7); ctx.fill();
+  }
+  ctx.globalAlpha = 1;
+
+  ctx.save();
+  if(shake>0) ctx.translate((Math.random()-.5)*6*shake,(Math.random()-.5)*6*shake);
+
+  // orbit guide
+  ctx.strokeStyle='rgba(255,255,255,.10)'; ctx.lineWidth=2; ctx.setLineDash([6,10]);
+  ctx.beginPath(); ctx.arc(CX,CY,ORBIT_R,0,Math.PI*2); ctx.stroke(); ctx.setLineDash([]);
+
+  // planet glow
+  const glow = ctx.createRadialGradient(CX,CY,PLANET_R*0.6,CX,CY,PLANET_R*1.5);
+  glow.addColorStop(0,'rgba(90,140,255,0)'); glow.addColorStop(.75,'rgba(90,140,255,.14)'); glow.addColorStop(1,'rgba(90,140,255,0)');
+  ctx.fillStyle=glow; ctx.beginPath(); ctx.arc(CX,CY,PLANET_R*1.5,0,7); ctx.fill();
+
+  // planet body
+  const pg = ctx.createRadialGradient(CX-PLANET_R*.35,CY-PLANET_R*.4,PLANET_R*.1,CX,CY,PLANET_R);
+  pg.addColorStop(0,'#3E6BE0'); pg.addColorStop(.55,'#27479F'); pg.addColorStop(1,'#16265E');
+  ctx.fillStyle=pg; ctx.beginPath(); ctx.arc(CX,CY,PLANET_R,0,7); ctx.fill();
+  // craters
+  ctx.fillStyle='rgba(255,255,255,.07)';
+  [[.3,-.2,.13],[-.35,.25,.17],[.05,.42,.09],[-.15,-.42,.07]].forEach(c=>{
+    ctx.beginPath(); ctx.arc(CX+c[0]*PLANET_R,CY+c[1]*PLANET_R,c[2]*PLANET_R,0,7); ctx.fill();
+  });
+  // grass rim
+  ctx.lineWidth=10; ctx.strokeStyle='#4ADE80';
+  ctx.beginPath(); ctx.arc(CX,CY,PLANET_R-2,0,7); ctx.stroke();
+  ctx.lineWidth=4; ctx.strokeStyle='#8FFFC0';
+  ctx.beginPath(); ctx.arc(CX,CY,PLANET_R-6,0,7); ctx.stroke();
+  // grass tufts around rim
+  ctx.strokeStyle='#4ADE80'; ctx.lineWidth=2.5; ctx.lineCap='round';
+  for(let i=0;i<48;i++){
+    const a=i/48*Math.PI*2 + Math.sin(t*.0006+i)*0.01;
+    const p1=pol(a,PLANET_R-3), p2=pol(a,PLANET_R+(i%2? 7:11));
+    ctx.beginPath(); ctx.moveTo(p1.x,p1.y); ctx.lineTo(p2.x,p2.y); ctx.stroke();
+  }
+  // decorative sprouts on planet
+  ctx.font='16px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
+  for(let i=0;i<5;i++){
+    const a=i/5*Math.PI*2+0.5, p=pol(a,PLANET_R*0.45);
+    ctx.fillText('🌱',p.x,p.y+Math.sin(t*.002+i)*2);
+  }
+  ctx.fillText('🏠',CX+Math.sin(t*.001)*2,CY+Math.cos(t*.0012)*2-6);
+
+  // fruits
+  for(const f of fruits){
+    if(f.taken) continue;
+    const bobY = Math.sin(f.bob)*4;
+    const p = pol(f.angle, ORBIT_R + bobY*0.3);
+    const pulse = 1 + Math.sin(f.bob*1.6)*0.08;
+    const s = Math.max(0.001, 22*f.scale*pulse);
+    // halo
+    const hr = Math.max(4, s*1.5);
+    const hg = ctx.createRadialGradient(p.x,p.y,2,p.x,p.y,hr);
+    hg.addColorStop(0,'rgba(255,209,102,.55)'); hg.addColorStop(1,'rgba(255,209,102,0)');
+    ctx.fillStyle=hg; ctx.beginPath(); ctx.arc(p.x,p.y,hr,0,7); ctx.fill();
+    // stem-to-planet tether
+    const base = pol(f.angle, PLANET_R+4);
+    ctx.strokeStyle='rgba(255,255,255,.35)'; ctx.lineWidth=2;
+    ctx.beginPath(); ctx.moveTo(base.x,base.y); ctx.lineTo(p.x,p.y+8); ctx.stroke();
+    ctx.font = Math.round(s*1.5)+'px serif';
+    ctx.fillText(f.emoji, p.x, p.y);
+  }
+
+  // ripples
+  for(const r of ripples){
+    const k=r.t/r.life;
+    ctx.strokeStyle='rgba(255,255,255,'+(0.7*(1-k))+')'; ctx.lineWidth=3;
+    ctx.beginPath(); ctx.arc(r.x,r.y,8+k*38,0,7); ctx.stroke();
+  }
+  // particles
+  for(const p of particles){
+    const k=1-p.t/p.life;
+    ctx.globalAlpha=Math.max(0,k); ctx.fillStyle=p.c;
+    ctx.beginPath(); ctx.arc(p.x,p.y,p.r*k+0.5,0,7); ctx.fill();
+  }
+  ctx.globalAlpha=1;
+
+  drawPlayer(t);
+
+  // floaters
+  ctx.textAlign='center'; ctx.textBaseline='middle';
+  for(const f of floaters){
+    const k=1-f.t/f.life;
+    ctx.globalAlpha=Math.min(1,k*1.6);
+    ctx.font='800 20px system-ui,sans-serif';
+    ctx.lineWidth=4; ctx.strokeStyle='rgba(0,0,0,.6)';
+    ctx.strokeText(f.text,f.x,f.y); ctx.fillStyle='#FFE66D'; ctx.fillText(f.text,f.x,f.y);
+  }
+  ctx.globalAlpha=1;
+
+  // confetti
+  for(const c of confetti){
+    ctx.save(); ctx.translate(c.x,c.y); ctx.rotate(c.rot);
+    ctx.globalAlpha=Math.min(1,c.life); ctx.fillStyle=c.c;
+    ctx.fillRect(-c.r,-c.r/2,c.r*2,c.r);
+    ctx.restore();
+  }
+  ctx.globalAlpha=1;
+  ctx.restore();
+
+  // center label
+  ctx.textAlign='center';
+  ctx.fillStyle='rgba(220,230,255,.75)';
+  ctx.font='700 13px system-ui,sans-serif';
+  ctx.fillText(state==='play' ? (FRUIT_GOAL-collected)+' FRUIT LEFT IN ORBIT' : 'ORBIT ORCHARD', CX, CY+PLANET_R+44);
+}
+
+function drawPlayer(t){
+  const p = pol(playerAngle, ORBIT_R);
+  const outward = playerAngle; // radial direction
+  ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(outward + Math.PI/2);
+  const bounce = moving ? Math.abs(Math.sin(runPhase))*2.2 : Math.sin(t*.003)*1.2;
+  ctx.translate(0,-14-bounce*0.4);
+  if(playerDir<0) ctx.scale(-1,1);
+  // shadow
+  ctx.fillStyle='rgba(0,0,0,.3)';
+  ctx.beginPath(); ctx.ellipse(0,16+bounce*0.4,10,3.5,0,0,7); ctx.fill();
+  // legs
+  const legSwing = moving ? Math.sin(runPhase)*5 : 0;
+  ctx.strokeStyle='#C7D2FE'; ctx.lineWidth=5; ctx.lineCap='round';
+  ctx.beginPath(); ctx.moveTo(-3,4); ctx.lineTo(-3-legSwing*0.4,14); ctx.stroke();
+  ctx.beginPath(); ctx.moveTo(3,4); ctx.lineTo(3+legSwing*0.4,14); ctx.stroke();
+  // boots
+  ctx.fillStyle='#334155';
+  ctx.beginPath(); ctx.ellipse(-3-legSwing*0.4,14,5,3,0,0,7); ctx.fill();
+  ctx.beginPath(); ctx.ellipse(3+legSwing*0.4,14,5,3,0,0,7); ctx.fill();
+  // body (suit)
+  ctx.fillStyle='#F8FAFC';
+  ctx.beginPath(); ctx.roundRect(-8,-10,16,16,7); ctx.fill();
+  ctx.fillStyle='#4ADE80'; ctx.fillRect(-8,-2,16,4); // garden stripe
+  // backpack
+  ctx.fillStyle='#94A3B8'; ctx.beginPath(); ctx.roundRect(-14,-8,6,12,3); ctx.fill();
+  // arm with basket
+  const armSwing = moving ? Math.sin(runPhase+1)*3 : Math.sin(t*.004)*1.5;
+  ctx.strokeStyle='#F8FAFC'; ctx.lineWidth=4.5;
+  ctx.beginPath(); ctx.moveTo(6,-4); ctx.lineTo(12,2+armSwing); ctx.stroke();
+  ctx.fillStyle='#B45309';
+  ctx.beginPath(); ctx.ellipse(14,5+armSwing,6,4.5,0,0,7); ctx.fill();
+  ctx.fillStyle='#92400E'; ctx.fillRect(8,1+armSwing,12,2);
+  // helmet
+  ctx.fillStyle='#F8FAFC'; ctx.beginPath(); ctx.arc(0,-16,10,0,7); ctx.fill();
+  ctx.fillStyle='#0EA5E9'; ctx.beginPath(); ctx.arc(2,-16,6,0,7); ctx.fill();
+  ctx.fillStyle='rgba(255,255,255,.75)'; ctx.beginPath(); ctx.arc(0,-18,2.2,0,7); ctx.fill();
+  // sprout on helmet 🌱
+  ctx.strokeStyle='#22C55E'; ctx.lineWidth=2;
+  ctx.beginPath(); ctx.moveTo(0,-26); ctx.lineTo(0,-30); ctx.stroke();
+  ctx.font='9px serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
+  ctx.fillText('🌱',0,-33);
+  ctx.restore();
+}
+
+/* ---------- loop ---------- */
+function frame(now){
+  requestAnimationFrame(frame);
+  const dt = Math.min(0.05,(now-lastT)/1000); lastT = now;
+  update(dt); draw(now);
+}
+resetGame();
+window.__orbit = {
+  get state(){ return state; },
+  get collected(){ return collected; },
+  get timeLeft(){ return timeLeft; },
+  set timeLeft(v){ timeLeft = v; },
+  start: startGame
+};
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

